from pathlib import Path
import tempfile

root = Path(__file__).resolve().parents[2]
source = (root / 'tools/pencil2-worker-v257/probe.py').read_text()
assert source.count('source = base.read_text()\n') == 1
source = source.replace('source = base.read_text()\n', 'source = base.read_text()\nsource = source.replace("p=(root/\'tools/pencil2-public-replay/drawing_native_target_translated_probe.py\').read_text()", "p=(root/\'tools/pencil2-public-replay/drawing_native_target_translated_probe.py\').read_text()\\np=p.replace(\\"  gl_simple.append([\'glBufferData\'\\", \\"  if size==4704 and raw is not None: open(\'/tmp/pencil259-native-geometry\',\'wb\').write(raw)\\\\n  gl_simple.append([\'glBufferData\'\\")")\n')
assert source.count('patch += "new_draw = new_draw.replace(\\"result=repr((observed,hex(selected_rt),\\", \\"result=repr((snapshots, [row for row in gl_simple if row[0] in (\'glGenTextures\',\'glBindTexture\',\'glTexImage2D\',\'glTexSubImage2D\',\'glUniform2fv\',\'glUniform1f\',\'glUniform1i\',\'glBlendFuncSeparate\',\'glBlendEquationSeparate\',\'glActiveTexture\',\'glUniformMatrix4fv\',\'glBindSampler\',\'glSamplerParameteri\',\'glTexParameteri\',\'glUseProgram\',\'glEnable\',\'glDisable\',\'glColorMask\',\'glGenFramebuffers\',\'glBindFramebuffer\',\'glFramebufferTexture2D\',\'glCheckFramebufferStatus\')], observed,hex(selected_rt),\\")\\n"\n') == 1
source = source.replace('patch += "new_draw = new_draw.replace(\\"result=repr((observed,hex(selected_rt),\\", \\"result=repr((snapshots, [row for row in gl_simple if row[0] in (\'glGenTextures\',\'glBindTexture\',\'glTexImage2D\',\'glTexSubImage2D\',\'glUniform2fv\',\'glUniform1f\',\'glUniform1i\',\'glBlendFuncSeparate\',\'glBlendEquationSeparate\',\'glActiveTexture\',\'glUniformMatrix4fv\',\'glBindSampler\',\'glSamplerParameteri\',\'glTexParameteri\',\'glUseProgram\',\'glEnable\',\'glDisable\',\'glColorMask\',\'glGenFramebuffers\',\'glBindFramebuffer\',\'glFramebufferTexture2D\',\'glCheckFramebufferStatus\')], observed,hex(selected_rt),\\")\\n"\n', 'patch += "new_draw = new_draw.replace(\\"result=repr((observed,hex(selected_rt),\\", \\"result=repr((snapshots, [row for row in gl_simple if row[0] in (\'glGenTextures\',\'glBindTexture\',\'glTexImage2D\',\'glTexSubImage2D\',\'glUniform2fv\',\'glUniform1f\',\'glUniform1i\',\'glBlendFuncSeparate\',\'glBlendEquationSeparate\',\'glActiveTexture\',\'glUniformMatrix4fv\',\'glBindSampler\',\'glSamplerParameteri\',\'glTexParameteri\',\'glUseProgram\',\'glEnable\',\'glDisable\',\'glColorMask\',\'glGenFramebuffers\',\'glBindFramebuffer\',\'glFramebufferTexture2D\',\'glCheckFramebufferStatus\',\'glBufferData\')], observed,hex(selected_rt),\\")\\n"\n')
assert source.count("        assert json.loads(json.dumps(calls)) == state_receipt['control' if control else 'draw']\n") == 1
source = source.replace("        assert json.loads(json.dumps(calls)) == state_receipt['control' if control else 'draw']\n", "        assert json.loads(json.dumps([row for row in calls if row[0] != 'glBufferData'])) == state_receipt['control' if control else 'draw']\n        assert [row[2] for row in calls if row[0] == 'glBufferData'] == [0, 0, 64, 0, 4704]\n")
with tempfile.TemporaryDirectory(prefix='pencil259-geometry-') as tmp:
    capture = Path(tmp) / 'native.vbo'
    source = source.replace('/tmp/pencil259-native-geometry', str(capture))
    exec(compile(source, str(root / 'tools/pencil2-worker-v259/probe.py'), 'exec'))
    assert capture.read_bytes() == (root / 'tools/pencil2-worker-v259/native-geometry.vbo').read_bytes()
    print('Verified native geometry upload.')
